def _resolve_effort_from_plan(agent_name: str, plan: InvocationPlan) -> str | None:
    if agent_name == "codex":
        return _config_override(plan.cmd, "model_reasoning_effort")
    from .agent_identity import is_hermes_grok_seat, is_native_grok_seat

    if agent_name == "claude" or is_native_grok_seat(agent_name):
        return _arg_after(plan.cmd, "--effort")
    if agent_name == "gemini":
        return None
    if agent_name in ("deepseek", "qwen") or is_hermes_grok_seat(agent_name):
        # Hermes -z mode: effort is config-scoped (~/.hermes/config.yaml),
        # not surfaced on the command line. Adapter logs a warning when the
        # caller's request disagrees with the config — telemetry has nothing
        # to resolve from the plan.
        return None
    if agent_name == "kimi":
        if plan.metadata.get("harness") == "kimicc":
            return "max" if plan.metadata.get("kimicc_alias") == "k3" else _NOT_EXPOSED
        # K3 is always-max; the k2.7 coding models expose no effort knob.
        # Read the resolved model off the plan so telemetry never mislabels
        # an ignored caller request as effective (#5326 multi-model lane).
        return "max" if _arg_after(plan.cmd, "-m") == "kimi-code/k3" else _NOT_EXPOSED
    return None


def _resolve_model_from_defaults(
    agent_name: str,
    requested_model: str | None,
    *,
    harness: str | None = None,
) -> str | None:
    if agent_name == "kimi" and harness == "kimicc":
        return requested_model or "k3"
    if requested_model:
        return requested_model
    if agent_name == "codex":
        # The codex adapter ALWAYS passes an explicit ``-m {registry default}``
        # when no override is given (adapters/codex.py::build_invocation), so
        # the registry — not ~/.codex/config.toml — is what actually runs.
        # Recording the user's config.toml model here mislabeled dispatches
        # (observed 2026-07-09: state file said gpt-5.6-sol while the CLI ran
        # -m gpt-5.6-terra). config.toml remains correct for EFFORT, where the
        # adapter genuinely falls through.
        registry_default = _default_model_for(agent_name)
        if registry_default:
            return registry_default
        value = _codex_config().get("model")
        return str(value).strip() if isinstance(value, str) and str(value).strip() else None
    if agent_name == "gemini":
        return _nested_lookup(
            _gemini_settings(),
            ("model", "defaultModel", "selectedModel", "modelName", "default_model"),
        )
    if agent_name in ("grok-hermes", "deepseek", "qwen"):
        return _default_model_for(agent_name)
    if agent_name == "claude":
        return _default_model_for(agent_name)
    return _default_model_for(agent_name)


def _resolve_effort_from_defaults(
    agent_name: str,
    requested_effort: str | None,
    *,
    harness: str | None = None,
) -> str | None:
    # These CLIs do not expose a per-invocation effort value.  A deliberate
    # marker is observability, not an error: warning on every dispatch made
    # routine task state look broken (#4837).
    from .agent_identity import is_hermes_grok_seat

    if agent_name in {"agy", "cursor", "gemini"}:
        return _NOT_EXPOSED
    if agent_name in {"deepseek", "qwen"} or is_hermes_grok_seat(agent_name):
        return _hermes_configured_effort() or _NOT_EXPOSED
    if agent_name == "kimi":
        if harness == "kimicc":
            return requested_effort if requested_effort else "max"
        # Without a plan the resolved model is unknowable (K3 is always-max,
        # the k2.7 models expose no effort knob) — report the honest marker
        # rather than guessing.
        return _NOT_EXPOSED
    if requested_effort:
        return requested_effort
    if agent_name == "codex":
        value = _codex_config().get("model_reasoning_effort")
        return str(value).strip() if isinstance(value, str) and str(value).strip() else None
    if agent_name == "claude":
        value = _claude_settings().get("effortLevel")
        return str(value).strip() if isinstance(value, str) and str(value).strip() else None
    if agent_name == "gemini":
        return _nested_lookup(
            _gemini_settings(),
            ("effort", "effortLevel", "reasoningEffort", "reasoning_effort"),
        )
    default_effort = _default_effort_for(agent_name)
    if default_effort:
        return default_effort
    return None

